#include <stdio.h>
#include <math.h>
typedef struct{float x,y,z;}V;
typedef struct{float t;V p,n;int h;}H;
static V v(float x,float y,float z){V r={x,y,z};return r;}
static V ad(V a,V b){return v(a.x+b.x,a.y+b.y,a.z+b.z);}
static V sb(V a,V b){return v(a.x-b.x,a.y-b.y,a.z-b.z);}
static V ml(V a,float s){return v(a.x*s,a.y*s,a.z*s);}
static float dt(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
static V nm(V a){float l=(float)sqrt((double)dt(a,a));return v(a.x/l,a.y/l,a.z/l);}
static V C={0,-0.5f,-5};
static H sp(V o,V d){
  H h={0};V oc=sb(o,C);
  float a=dt(d,d),b=2*dt(oc,d),c=dt(oc,oc)-1.0f*1.0f,D=b*b-4.0f*a*c,t;
  if(D<0)return h;
  t=(float)(((double)-b-sqrt((double)D))/(double)(a+a));
  if(t<0.001f){t=(float)(((double)-b+sqrt((double)D))/(double)(a+a));if(t<0.001f)return h;}
  h.h=1;h.t=t;h.p=ad(o,ml(d,t));h.n=nm(sb(h.p,C));return h;
}
static H pl(V o,V d){
  H h={0};float t;
  if(fabsf(d.y)<1e-4f)return h;
  t=(-1.5f-o.y)/d.y;if(t<0.001f)return h;
  h.h=1;h.t=t;h.p=ad(o,ml(d,t));h.n=v(0,1,0);return h;
}
int main(){
  int W=2400,Hh=1800,i,j,s;
  V O=v(0,0,0),L=nm(v(1,1,-1));
  float vh=2.0f,vw=(float)W/(float)Hh*vh;
  V hz=v(vw,0,0),vt=v(0,vh,0),ll=sb(sb(sb(O,ml(hz,0.5f)),ml(vt,0.5f)),v(0,0,1));
  FILE*f=fopen("reconstructed.ppm","w");
  fprintf(f,"P3\n%d %d\n255\n",W,Hh);
  for(j=0;j<Hh;j++)for(i=0;i<W;i++){
    float u=(float)i/(float)(W-1),w=(float)j/(float)(Hh-1),df;
    V d=nm(ad(ll,ad(ml(hz,u),sb(ml(vt,1.0f-w),O)))),c;
    H a=sp(O,d),b=pl(O,d),h;
    if(a.h&&(!b.h||b.t>a.t)){h=a;s=1;}
    else if(b.h){h=b;s=0;}
    else{float t=0.5f*(d.y+1.0f);c=ad(ml(v(1,1,1),1.0f-t),ml(v(0.5f,0.7f,1.0f),t));goto out;}
    df=(float)fmax((double)dt(h.n,L),0.0);
    if(sp(ad(h.p,ml(h.n,0.001f)),L).h)df=0;
    df=(1.0f-0.2f)*df+0.2f;
    if(s)c=ml(v(1,0.2f,0.2f),df);
    else{float k=((int)(floor((double)h.p.x)+floor((double)h.p.z))&1)?0.4f:0.9f;c=ml(v(k,k,k),df);}
    out:
    fprintf(f,"%d %d %d\n",(int)(fmin(fmax(c.x,0),1)*255.99f),(int)(fmin(fmax(c.y,0),1)*255.99f),(int)(fmin(fmax(c.z,0),1)*255.99f));
  }
  fclose(f);return 0;
}

